// GetMspAdoptTip MSP get adopt tip
//
// Corresponds with GET /openapi/v1/msp/{mspId}/adopt-tip (the `GetMspAdoptTip` operationId).
func (c *Client) GetMspAdoptTip(ctx context.Context, mspId string, reqEditors ...RequestEditorFn) (*http.Response, error) {
	req, err := NewGetMspAdoptTipRequest(c.Server, mspId)
	if err != nil {
		return nil, err
	}
	req = req.WithContext(ctx)
	if err := c.applyEditors(ctx, req, reqEditors); err != nil {
		return nil, err
	}
	return c.Client.Do(req)
}

